553	  putreg32(DMA_STAT_FIN_INT | DMA_STAT_HALF_INT | DMA_STAT_BUS_ERR_INT,
554	           DMA_CH_STATUS(ch));
555	
556	  /* Source: the peripheral FIFO port.  Same AVDK loop trick as the
557	   * playback destination above -- advance the internal pointer across a
558	   * 4-byte window so the request line re-asserts every beat.
559	   */
560	
561	  putreg32((uint32_t)cfg->src,                DMA_CH_SRC_ADDR(ch));
562	  putreg32((uint32_t)cfg->src,                DMA_CH_SRC_LOOP_START(ch));
563	  putreg32((uint32_t)cfg->src + 4u,           DMA_CH_SRC_LOOP_END(ch));
564	
565	  /* Destination: memory buffer, auto-increment, loop when circular. */
566	
567	  putreg32((uint32_t)cfg->buf,                DMA_CH_DST_ADDR(ch));
568	  if (!cfg->one_shot)
569	    {
570	      putreg32((uint32_t)cfg->buf,            DMA_CH_DST_LOOP_START(ch));
571	      putreg32((uint32_t)(cfg->buf + cfg->buf_len),
572	               DMA_CH_DST_LOOP_END(ch));
573	    }
574	  else
575	    {
576	      putreg32(0, DMA_CH_DST_LOOP_START(ch));
577	      putreg32(0, DMA_CH_DST_LOOP_END(ch));
578	    }
579	
580	  /* Request-mux: source from the peripheral, destination to memory. */
581	
582	  reqmux = ((uint32_t)cfg->src_req_mux & DMA_REQ_MUX_MASK)
583	                << DMA_REQ_SRC_MUX_SHIFT;
584	  reqmux |= ((uint32_t)BK7258_DMA_REQ_MEM & DMA_REQ_MUX_MASK)
585	                << DMA_REQ_DST_MUX_SHIFT;
586	  reqmux |= DMA_REQ_BUS_ERR_INT_EN;
587	#ifdef CONFIG_ARCH_TRUSTZONE_SECURE
588	  reqmux |= DMA_REQ_SRC_SEC_ATTR | DMA_REQ_DST_SEC_ATTR;
589	#endif
590	  putreg32(reqmux, DMA_CH_REQ_MUX(ch));
591	
592	  ctrl  = DMA_CTRL_FIN_INT_EN
593	        | DMA_CTRL_SRC_INC_EN
594	        | DMA_CTRL_DST_INC_EN
595	        | DMA_CTRL_SRC_LOOP_EN;
596	
597	  if (!cfg->one_shot)
598	    {
599	      ctrl |= DMA_CTRL_MODE_REPEAT
600	            | DMA_CTRL_HALF_INT_EN
601	            | DMA_CTRL_DST_LOOP_EN;
602	    }
603	
604	  ctrl |= ((uint32_t)cfg->src_width & DMA_CTRL_WIDTH_MASK)
605	                << DMA_CTRL_SRC_WIDTH_SHIFT;
606	  ctrl |= ((uint32_t)cfg->dst_width & DMA_CTRL_WIDTH_MASK)
607	                << DMA_CTRL_DST_WIDTH_SHIFT;
608	  ctrl |= (transfer_len & 0xFFFFu) << DMA_CTRL_TRANSFER_LEN_SHIFT;
609	  putreg32(ctrl, DMA_CH_CTRL(ch));
610	
611	  /* DMA is writing into RAM: invalidate before the transfer so stale
612	   * cache lines cannot overwrite the captured samples.
613	   */
614	
615	#ifdef CONFIG_ARMV8M_DCACHE
616	  up_invalidate_dcache(cfg->buf, cfg->buf + cfg->buf_len);
617	#endif
618	
619	  ctrl = getreg32(DMA_CH_CTRL(ch));
620	  ctrl |= DMA_CTRL_ENABLE;
621	  putreg32(ctrl, DMA_CH_CTRL(ch));
622	
623	  audinfo("BK7258 GDMA ch%d p2m started: ctrl=0x%08lx src=0x%08lx dst=0x%08lx "
624	          "reqmux=0x%08lx bytes=%lu\n",
625	          ch, (unsigned long)ctrl, (unsigned long)cfg->src,
626	          (unsigned long)cfg->buf,
627	          (unsigned long)getreg32(DMA_CH_REQ_MUX(ch)),
628	          (unsigned long)cfg->buf_len);

