static void capture_notify_dequeue(FAR struct bk7258_capture_s *priv,
                                   FAR struct ap_buffer_s *apb, int result)
{
#ifdef CONFIG_AUDIO_MULTI_SESSION
  priv->dev.upper(priv->dev.priv, AUDIO_CALLBACK_DEQUEUE, apb, result, NULL);
#else
  priv->dev.upper(priv->dev.priv, AUDIO_CALLBACK_DEQUEUE, apb, result);
#endif
}

/* Same shape as the playback half's bk7258_volume_to_gain(): the upper
 * half speaks 0..100 and the hardware wants the 6-bit ADC gain 0..0x3F.
 * Volume 72 rounds to 45 = 0x2d, Armino's DEFAULT_AUD_ADC_CONFIG().adc_gain.
 */

#define BK7258_ADC_VOLUME_DEFAULT  72u
#define BK7258_ADC_GAIN_MAX        0x3Fu

static uint8_t capture_volume_to_gain(uint8_t volume)
{
  return (uint8_t)(((uint32_t)volume * BK7258_ADC_GAIN_MAX) / 100u);
}

static void capture_notify_complete(FAR struct bk7258_capture_s *priv)
{
#ifdef CONFIG_AUDIO_MULTI_SESSION
  priv->dev.upper(priv->dev.priv, AUDIO_CALLBACK_COMPLETE, NULL, OK, NULL);
#else
  priv->dev.upper(priv->dev.priv, AUDIO_CALLBACK_COMPLETE, NULL, OK);
#endif
}

static void capture_start_dma(FAR struct bk7258_capture_s *priv)
{
  FAR struct ap_buffer_s *apb;
  struct bk7258_dma_p2m_cfg_s cfg;
  int ret;

  /* Buffers queued before AUDIOIOC_START wait here; capture_start() kicks
   * the DMA once the ADC is running.
   */

  if (!priv->running || priv->paused || priv->stopping ||
      priv->dma_active || priv->dma_ch < 0)
    {
      return;
    }

  apb = (FAR struct ap_buffer_s *)dq_peek(&priv->pendq);
  if (apb == NULL)
    {
      return;
    }

  cfg.buf         = (uintptr_t)apb->samp;
  cfg.buf_len     = apb->nmaxbytes;
  cfg.src         = bk7258_adc_fifo_addr();
  cfg.src_req_mux = BK7258_DMA_REQ_AUDIO_ADC;
  /* AUD_ADC_FPORT is a single 32-bit register; one beat is a stereo frame
   * or two mono samples.  Both widths 32-bit, same rule as the playback
   * path documents for AUD_DAC_FPORT.
   */

  cfg.src_width   = BK7258_DMA_WIDTH_32;
  cfg.dst_width   = BK7258_DMA_WIDTH_32;
  cfg.one_shot    = true;
  cfg.callback    = capture_dma_cb;
  cfg.arg         = priv;

  ret = bk7258_gdma_start_p2m(priv->dma_ch, &cfg);
  if (ret < 0)
    {
      AUD_ERR("gdma_start_p2m failed: %d", ret);
      return;
    }

  priv->dma_active = true;
  priv->dma_apb    = apb;
}

static void capture_dma_cb(int ch, uint32_t event, FAR void *arg)
{
  FAR struct bk7258_capture_s *priv = arg;
  FAR struct ap_buffer_s *apb;
  irqstate_t flags;

  (void)ch;

  flags = spin_lock_irqsave(&priv->lock);
  apb = priv->dma_apb;
  priv->dma_apb    = NULL;
  priv->dma_active = false;

  if (apb != NULL && (event & BK7258_DMA_EVENT_BUS_ERROR) == 0)
    {
      dq_rem(&apb->dq_entry, &priv->pendq);
      apb->nbytes = apb->nmaxbytes;
      if (priv->readmode)
        {
          apb->curbyte = 0;
          dq_addlast(&apb->dq_entry, &priv->doneq);
          spin_unlock_irqrestore(&priv->lock, flags);
          nxsem_post(&priv->readsem);
        }
      else
        {
          spin_unlock_irqrestore(&priv->lock, flags);
          capture_notify_dequeue(priv, apb, OK);
        }
    }
  else
    {
      spin_unlock_irqrestore(&priv->lock, flags);
    }

  capture_start_dma(priv);
}

static int capture_getcaps(FAR struct audio_lowerhalf_s *dev, int type,
                           FAR struct audio_caps_s *caps)
{
  (void)dev;
  (void)type;

  /* nxrecorder picks a device by asking AUDIO_TYPE_QUERY and then testing
   * ac_controls.b[0] & AUDIO_TYPE_INPUT (nxrecorder.c:206).  Answering
   * with ac_type = AUDIO_TYPE_INPUT instead leaves b[0] zero and the
   * search reports "No suitable Audio Device".
   */

  caps->ac_format.hw   = 0;
  caps->ac_controls.w  = 0;

  switch (caps->ac_type)
    {
      case AUDIO_TYPE_QUERY:
        caps->ac_channels = 1;
        switch (caps->ac_subtype)
          {
            case AUDIO_TYPE_QUERY:
              caps->ac_controls.b[0] = AUDIO_TYPE_INPUT | AUDIO_TYPE_FEATURE;
              caps->ac_format.hw     = 1 << (AUDIO_FMT_PCM - 1);
              break;

            case AUDIO_FMT_PCM:
              caps->ac_controls.b[0] = AUDIO_SUBFMT_PCM_S16_LE;
              break;

                             BK7258_APLL_CONFIG_VAL);
  if (ret < 0)
    {
      return ret;
    }

  ret = bk7258_ana_reg_bit(BK7258_ANA_REG25_APLL_CFG,
                           ANA_REG25_SPI_TRIGGER_BIT, 0x1u, 1);
  if (ret < 0)
    {
      return ret;
    }

  up_mdelay(20);

  return bk7258_ana_reg_bit(BK7258_ANA_REG25_APLL_CFG,
                            ANA_REG25_SPI_TRIGGER_BIT, 0x1u, 0);
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int bk7258_adc_configure(const struct bk7258_adc_cfg_s *cfg)
{
  irqstate_t flags;
  uint32_t v;
  int ret;

  if (cfg == NULL)
    {
      return -EINVAL;
    }

  ret = bk7258_aud_subsystem_init();
  if (ret < 0)
    {
      return ret;
    }

  g_bk7258_adc_use_apll = cfg->use_apll;

  /* Clock select — identical to the DAC configure() clock block; the audio
   * clock mux is shared between the DAC and ADC paths.
   */

  if (cfg->use_apll)
    {
      bk7258_sys_reg_bits(SYS_CLK_DIV_MODE1,
                          SYS_CLK_DIV_MODE1_CKSEL_AUD_MASK
                              << SYS_CLK_DIV_MODE1_CKSEL_AUD_BIT,
                          UINT32_C(1) << SYS_CLK_DIV_MODE1_CKSEL_AUD_BIT);

      ret = bk7258_apll_program(BK7258_APLL_CAL_VAL_48K);
      if (ret < 0)
        {
          return ret;
        }

      v = getreg32(BK7258_AUD_AUDIO_CONFIG);
      v |= AUD_AUDIO_CFG_APLL_SEL;
      putreg32(v, BK7258_AUD_AUDIO_CONFIG);

      bk7258_sys_reg_bits(SYS_CLK_DIV_MODE2,
                          UINT32_C(1) << SYS_CLK_DIV_MODE2_DMIC_DIV_BIT,
                          UINT32_C(1) << SYS_CLK_DIV_MODE2_DMIC_DIV_BIT);
    }
  else
    {
      bk7258_sys_reg_bits(SYS_CLK_DIV_MODE1,
                          SYS_CLK_DIV_MODE1_CKSEL_AUD_MASK
                              << SYS_CLK_DIV_MODE1_CKSEL_AUD_BIT,
                          0u);

      v = getreg32(BK7258_AUD_AUDIO_CONFIG);
      v &= ~AUD_AUDIO_CFG_APLL_SEL;
      putreg32(v, BK7258_AUD_AUDIO_CONFIG);
    }

  /* Analog MIC preamp enable.  On BK7258 only micen (ana_reg19[28]) is wired;
   * AVDK's mic2_en is a no-op, so dual-MIC shares this one bit.  Order matches
   * aud_adc_driver.c: micen -> biases -> reset pulse.
   */

  ret = bk7258_ana_reg_bit(BK7258_ANA_REG19,
                           ANA_REG19_MICEN_BIT, 0x1u, 1);
  if (ret < 0)
    {
      return ret;
    }

  ret = bk7258_ana_reg_bit(BK7258_ANA_REG18,
                           ANA_REG18_ENADCBias_BIT, 0x1u, 1);
  if (ret < 0)
    {
      return ret;
    }

  ret = bk7258_ana_reg_bit(BK7258_ANA_REG18,
                           ANA_REG18_ENMICBias_BIT, 0x1u, 1);
  if (ret < 0)
    {
      return ret;
    }

  /* MIC reset pulse after parameter config (aud_adc_driver.c:104..106). */

  ret = bk7258_ana_reg_bit(BK7258_ANA_REG19,
                           ANA_REG19_MIC_RST_BIT, 0x1u, 1);
  if (ret < 0)
    {
      return ret;
    }

  up_mdelay(10);

  ret = bk7258_ana_reg_bit(BK7258_ANA_REG19,
                           ANA_REG19_MIC_RST_BIT, 0x1u, 0);
  if (ret < 0)
    {
      return ret;
    }

  /* Digital path: gain, sample edge, HPF bypass. */

  flags = spin_lock_irqsave(&g_bk7258_adc_lock);
  v = getreg32(BK7258_AUD_ADC_CONFIG0);
  v &= ~(AUD_ADC_CFG0_GAIN_MASK | AUD_ADC_CFG0_SAMP_EDGE
         | AUD_ADC_CFG0_HPF1_BYPASS | AUD_ADC_CFG0_HPF2_BYPASS);
  v |= ((uint32_t)(cfg->gain & 0x3Fu) << AUD_ADC_CFG0_GAIN_SHIFT);
  if (cfg->samp_edge)
    {
      v |= AUD_ADC_CFG0_SAMP_EDGE;
    }
  v |= AUD_ADC_CFG0_HPF1_BYPASS | AUD_ADC_CFG0_HPF2_BYPASS;
  putreg32(v, BK7258_AUD_ADC_CONFIG0);
  spin_unlock_irqrestore(&g_bk7258_adc_lock, flags);

  /* Sample-rate divider. */

  ret = bk7258_adc_set_sample_rate(cfg->samp_rate);
  if (ret < 0)
    {
      return ret;
    }

  bk7258_adc_set_adcl_wr_threshold(BK7258_ADC_ADCL_WR_TH_DEFAULT);

  g_bk7258_adc_configured = true;
  return OK;
}

int bk7258_adc_set_sample_rate(uint32_t samp_rate)
{
  uint32_t sr_code;
  bool     apll_44k_family = false;
  uint32_t v;
  int ret;

  switch (samp_rate)
    {
      case 8000:
        sr_code = AUD_SAMP_RATE_8K;
        break;

      case 16000:
        sr_code = AUD_SAMP_RATE_16K;
        break;

      case 44100:
        sr_code = AUD_SAMP_RATE_44_1K;
        apll_44k_family = true;
        break;

      case 48000:
        sr_code = AUD_SAMP_RATE_48K;
        break;

      default:
        auderr("BK7258: unsupported ADC sample rate %lu\n",
               (unsigned long)samp_rate);
        return -EINVAL;
    }

  /* On APLL, the 44.1k family requires a different cal value. */

  if (g_bk7258_adc_use_apll)
    {
      ret = bk7258_apll_program(apll_44k_family
                                    ? BK7258_APLL_CAL_VAL_44_1K
                                    : BK7258_APLL_CAL_VAL_48K);
      if (ret < 0)
        {
          return ret;
        }
    }

  /* Standard rates use the auto divider: clear adc_fracmod_manual, then set
   * samp_rate_ADC [1:0] (distinct from samp_rate_DAC [7:6]).
   */

  v = getreg32(BK7258_AUD_EXTEND_CFG);
  v &= ~AUD_EXT_CFG_ADC_FRACMOD_MAN;
  putreg32(v, BK7258_AUD_EXTEND_CFG);

  v = getreg32(BK7258_AUD_AUDIO_CONFIG);
  v &= ~AUD_AUDIO_CFG_SAMP_RATE_ADC_MASK;
  v |= (sr_code << AUD_AUDIO_CFG_SAMP_RATE_ADC_SHIFT)
       & AUD_AUDIO_CFG_SAMP_RATE_ADC_MASK;
  putreg32(v, BK7258_AUD_AUDIO_CONFIG);

  return OK;
}

int bk7258_adc_set_gain(uint8_t gain)
{
  irqstate_t flags;
  uint32_t v;

  if (gain > 0x3Fu)
    {
      gain = 0x3Fu;
    }

  flags = spin_lock_irqsave(&g_bk7258_adc_lock);
  v = getreg32(BK7258_AUD_ADC_CONFIG0);
  v &= ~AUD_ADC_CFG0_GAIN_MASK;
  v |= ((uint32_t)gain << AUD_ADC_CFG0_GAIN_SHIFT);
  putreg32(v, BK7258_AUD_ADC_CONFIG0);
  spin_unlock_irqrestore(&g_bk7258_adc_lock, flags);

  return OK;
}

void bk7258_adc_start(void)
{
  irqstate_t flags;
  uint32_t v;

  flags = spin_lock_irqsave(&g_bk7258_adc_lock);
  v = getreg32(BK7258_AUD_AUDIO_CONFIG);
  v |= (AUD_AUDIO_CFG_ADC_ENABLE | AUD_AUDIO_CFG_LINE_ENABLE);
  putreg32(v, BK7258_AUD_AUDIO_CONFIG);
  spin_unlock_irqrestore(&g_bk7258_adc_lock, flags);
}

void bk7258_adc_stop(void)
{
  irqstate_t flags;
  uint32_t v;

  flags = spin_lock_irqsave(&g_bk7258_adc_lock);
  v = getreg32(BK7258_AUD_AUDIO_CONFIG);
  v &= ~(AUD_AUDIO_CFG_ADC_ENABLE | AUD_AUDIO_CFG_LINE_ENABLE);
  putreg32(v, BK7258_AUD_AUDIO_CONFIG);
  spin_unlock_irqrestore(&g_bk7258_adc_lock, flags);
}

uintptr_t bk7258_adc_fifo_addr(void)
{
  return (uintptr_t)BK7258_AUD_ADC_FPORT;
}

uint32_t bk7258_adc_fifo_read(void)
{
  return getreg32(BK7258_AUD_ADC_FPORT);
}

/* AUD_FIFO_ST_ADCL_EMPTY is bit 14 of the shared FIFO status word.  Kept
 * here rather than in the caller: the register read belongs to the HAL,
 * and the caller is an application that has no business doing MMIO.

  NULL,
#endif
  NULL,                  /* allocbuffer    */
  NULL,                  /* freebuffer     */
  capture_enqueuebuffer,
  capture_cancelbuffer,
  capture_ioctl,
  capture_read,
  NULL,                  /* write          */
  capture_reserve,
  capture_release
};

static void capture_notify_dequeue(FAR struct bk7258_capture_s *priv,
                                   FAR struct ap_buffer_s *apb, int result)
{
#ifdef CONFIG_AUDIO_MULTI_SESSION
  priv->dev.upper(priv->dev.priv, AUDIO_CALLBACK_DEQUEUE, apb, result, NULL);
#else
  priv->dev.upper(priv->dev.priv, AUDIO_CALLBACK_DEQUEUE, apb, result);
#endif
}

/* Same shape as the playback half's bk7258_volume_to_gain(): the upper
 * half speaks 0..100 and the hardware wants the 6-bit ADC gain 0..0x3F.
 * Volume 72 rounds to 45 = 0x2d, Armino's DEFAULT_AUD_ADC_CONFIG().adc_gain.
 */

#define BK7258_ADC_VOLUME_DEFAULT  72u
#define BK7258_ADC_GAIN_MAX        0x3Fu

static uint8_t capture_volume_to_gain(uint8_t volume)
{
  return (uint8_t)(((uint32_t)volume * BK7258_ADC_GAIN_MAX) / 100u);
}

static void capture_notify_complete(FAR struct bk7258_capture_s *priv)
{
#ifdef CONFIG_AUDIO_MULTI_SESSION
  priv->dev.upper(priv->dev.priv, AUDIO_CALLBACK_COMPLETE, NULL, OK, NULL);
#else
  priv->dev.upper(priv->dev.priv, AUDIO_CALLBACK_COMPLETE, NULL, OK);
#endif
}

static void capture_start_dma(FAR struct bk7258_capture_s *priv)
{
  FAR struct ap_buffer_s *apb;
  struct bk7258_dma_p2m_cfg_s cfg;
  int ret;

  /* Buffers queued before AUDIOIOC_START wait here; capture_start() kicks
   * the DMA once the ADC is running.
   */

  if (!priv->running || priv->paused || priv->stopping ||
      priv->dma_active || priv->dma_ch < 0)
    {
      return;
    }

  apb = (FAR struct ap_buffer_s *)dq_peek(&priv->pendq);
  if (apb == NULL)
    {
      return;
    }

  cfg.buf         = (uintptr_t)apb->samp;
  cfg.buf_len     = apb->nmaxbytes;
  cfg.src         = bk7258_adc_fifo_addr();
  cfg.src_req_mux = BK7258_DMA_REQ_AUDIO_ADC;
  /* AUD_ADC_FPORT is a single 32-bit register; one beat is a stereo frame
   * or two mono samples.  Both widths 32-bit, same rule as the playback
   * path documents for AUD_DAC_FPORT.
   */

  cfg.src_width   = BK7258_DMA_WIDTH_32;
  cfg.dst_width   = BK7258_DMA_WIDTH_32;
  cfg.one_shot    = true;
  cfg.callback    = capture_dma_cb;
  cfg.arg         = priv;

  ret = bk7258_gdma_start_p2m(priv->dma_ch, &cfg);
  if (ret < 0)
    {
      AUD_ERR("gdma_start_p2m failed: %d", ret);
      return;
    }

  priv->dma_active = true;
  priv->dma_apb    = apb;
}

static void capture_dma_cb(int ch, uint32_t event, FAR void *arg)
{
  FAR struct bk7258_capture_s *priv = arg;
  FAR struct ap_buffer_s *apb;
  irqstate_t flags;

  (void)ch;

  flags = spin_lock_irqsave(&priv->lock);
  apb = priv->dma_apb;
  priv->dma_apb    = NULL;
  priv->dma_active = false;

  if (apb != NULL && (event & BK7258_DMA_EVENT_BUS_ERROR) == 0)
    {
      dq_rem(&apb->dq_entry, &priv->pendq);
      apb->nbytes = apb->nmaxbytes;
      if (priv->readmode)
        {
          apb->curbyte = 0;
          dq_addlast(&apb->dq_entry, &priv->doneq);
          spin_unlock_irqrestore(&priv->lock, flags);
          nxsem_post(&priv->readsem);
        }
      else
        {
          spin_unlock_irqrestore(&priv->lock, flags);
          capture_notify_dequeue(priv, apb, OK);
        }
    }
  else
    {
      spin_unlock_irqrestore(&priv->lock, flags);
    }

  capture_start_dma(priv);
}

