  FAR struct ap_buffer_s *apb;
  irqstate_t flags;

  priv->running  = false;
  priv->stopping = true;

  if (priv->dma_active)
    {
      bk7258_gdma_stop(priv->dma_ch);
      priv->dma_active = false;
      priv->dma_apb    = NULL;
    }

