static bk_err_t _onboard_mic_open(audio_element_handle_t self)
{
    BK_LOGD(TAG, "[%s] %s\n", audio_element_get_tag(self), __func__);

    onboard_mic_stream_t *onboard_mic = (onboard_mic_stream_t *)audio_element_getdata(self);

