    //audio_element_set_input_timeout(self, 15 / portTICK_RATE_MS);
    ring_buffer_clear(&onboard_mic->mic_rb);

    bk_err_t ret = bk_dma_start(onboard_mic->mic_dma_id);
    if (ret != BK_OK)
    {
        BK_LOGE(TAG, "%s, %d, adc dma start fail\n", __func__, __LINE__);
        return BK_FAIL;
