            * push the compacted samples back out.  The clean matters -- the
            * reader invalidates the buffer again before its first copy.
            */

     #ifdef CONFIG_ARMV8M_DCACHE
           up_invalidate_dcache((uintptr_t)apb->samp,
                                (uintptr_t)apb->samp + apb->nmaxbytes);
